import{_ as a,o as s,c as e,ag as n}from"./chunks/framework.D2veAa-g.js";const b=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成-内存地址与芯片计算","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成-内存地址与芯片计算"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成/内存地址与芯片计算.md","filePath":"综合知识/系统基础/计算机组成/内存地址与芯片计算.md","lastUpdated":null}'),o={name:"综合知识/系统基础/计算机组成/内存地址与芯片计算.md"};function d(i,t,l,r,p,c){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 十六进制地址范围 → 字节数计算</li><li>[x] 存储器芯片数量计算</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="地址范围-→-内存容量" tabindex="-1">地址范围 → 内存容量 <a class="header-anchor" href="#地址范围-→-内存容量" aria-label="Permalink to &quot;地址范围 → 内存容量&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>内存容量 = 末地址 - 首地址 + 1</strong>（注意是闭区间，必须 +1），结果按 K=1024 换算。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>容量(字节) = 末地址 - 首地址 + 1</span></span>
<span class="line"><span>K = 1024 = 2^10</span></span>
<span class="line"><span>M = 1024K = 2^20</span></span></code></pre></div><p><strong>十六进制减法</strong>：</p><table tabindex="0"><thead><tr><th>步骤</th><th>操作</th><th>示例</th></tr></thead><tbody><tr><td>1</td><td>末地址 - 首地址</td><td>DFFFFH - B0000H = 2FFFFH</td></tr><tr><td>2</td><td>+1</td><td>2FFFFH + 1 = <strong>30000H</strong></td></tr><tr><td>3</td><td>转十进制</td><td>3 × 16^4 = 3 × 65536 = <strong>196608</strong>（字节）</td></tr></tbody></table><blockquote><p>易记：16^4 = 65536，16^5 = 1048576（1M）</p></blockquote><h3 id="芯片数量计算" tabindex="-1">芯片数量计算 <a class="header-anchor" href="#芯片数量计算" aria-label="Permalink to &quot;芯片数量计算&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>芯片数 = 总容量(bits) ÷ 单芯片容量(bits)</strong>，注意区分 byte 和 bit 的换算。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>芯片数 = 总容量(bit) / 单芯片容量(bit)</span></span></code></pre></div><p><strong>单位换算关键</strong>：</p><ul><li>芯片规格通常写为 <strong>&quot;容量 × 位宽&quot;</strong>，如 <code>64K×4bit</code> 表示 64K 个存储单元，每个 4bit</li><li>总容量用字节时：<strong>1 byte = 8 bit</strong></li></ul><p><strong>计算示例</strong>：</p><blockquote><p>内存 196608 字节（地址 B0000H～DFFFFH），用 64K×4bit 芯片</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总容量 = 196608 × 8 = 1,572,864 bit</span></span>
<span class="line"><span>单芯片 = 64 × 1024 × 4 = 262,144 bit</span></span>
<span class="line"><span>芯片数 = 1,572,864 / 262,144 = 6 片</span></span></code></pre></div><h3 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>易错点</th><th>正解</th></tr></thead><tbody><tr><td>忘了 +1</td><td>地址范围 B0000H～DFFFFH 包含两端，末-首后<strong>必须+1</strong></td></tr><tr><td>16^4 算错</td><td>16^4 = 65536（不是 65535），16^3 = 4096</td></tr><tr><td>bit/byte 混淆</td><td>芯片规格写的是 <strong>bit</strong>，内存容量写的是<strong>字节</strong>，须 ×8 换算</td></tr><tr><td>K vs k</td><td>计算机中 1K = 1024（不是 1000），64K = 64×1024</td></tr></tbody></table>`,19)])])}const u=a(o,[["render",d]]);export{b as __pageData,u as default};
